const size_t max_iterations = ckh->capacity * 2;
    size_t iterations = 0;
    size_t bucket = argbucket;
    const void *key = argkey;
    const void *data = argdata;
    const void *evicted_key = nullptr;
    const void *evicted_data = nullptr;
    size_t evicted_bucket = 0;

    while (iterations < max_iterations) {
        // Try to insert into current bucket
        if (ckh->table[bucket].key == nullptr) {
            ckh->table[bucket].key = key;
            ckh->table[bucket].data = data;
            ckh->count++;
            return false;
        }

        // Evict existing element
        evicted_key = ckh->table[bucket].key;
        evicted_data = ckh->table[bucket].data;
        evicted_bucket = bucket;

        // Insert new element
        ckh->table[bucket].key = key;
        ckh->table[bucket].data = data;

        // Find alternative bucket for evicted element
        size_t alt_bucket = ckh->hash2(evicted_key) % ckh->capacity;
        if (alt_bucket == evicted_bucket) {
            alt_bucket = (alt_bucket + 1) % ckh->capacity;
        }

        // Prepare for next iteration
        key = evicted_key;
        data = evicted_data;
        bucket = alt_bucket;
        iterations++;
    }

    // Max iterations reached, insertion failed
    return true;

